// `outcome` is the aggregate verdict (honors testset runners). Counts are
// leaf-level: `failed` = hard failures, `tolerated` = failing leaves whose
// enclosing testset runner still passed (e.g. under `PassRate`), `passed` and
// `total` as usual. `failed_names` are the hard-failure names; `messages` are
// every failing run's message. The three name arrays partition selected leaf
// IDs by their actual outcome after applying testset-runner tolerance.
type FlatTestReportStream struct {
	Outcome        *StringLiteral8f01a46bOrStringLiterald213b5e2OrStringLiteralfe355433 `json:"outcome" baml:"outcome"`
	Passed         *int64                                                               `json:"passed" baml:"passed"`
	Failed         *int64                                                               `json:"failed" baml:"failed"`
	Tolerated      *int64                                                               `json:"tolerated" baml:"tolerated"`
	Total          *int64                                                               `json:"total" baml:"total"`
	PassedNames    []string                                                             `json:"passed_names" baml:"passed_names"`
	FailedNames    []string                                                             `json:"failed_names" baml:"failed_names"`
	ToleratedNames []string                                                             `json:"tolerated_names" baml:"tolerated_names"`
	Messages       []string                                                             `json:"messages" baml:"messages"`
}

func (FlatTestReportStream) BAMLClassName() string { return "testing.FlatTestReport$stream" }

